import { context } from "@opentelemetry/api";
import { telemetryStoreFrom } from "./session-telemetry.js";
/** Copy the active turn's trace tags onto a span when it starts. */
export function telemetrySpanProcessor() {
    return {
        onStart(span, parentContext) {
            const store = telemetryStoreFrom(parentContext);
            if (store === undefined) {
                return;
            }
            if (Object.keys(store.span).length === 0) {
                return;
            }
            span.setAttributes(store.span);
        },
        onEnd() { },
        shutdown() {
            return Promise.resolve();
        },
        forceFlush() {
            return Promise.resolve();
        },
    };
}
/** Copy the active turn's log tags onto a record when it is emitted. */
export function telemetryLogProcessor() {
    return {
        onEmit(record, recordContext) {
            const store = telemetryStoreFrom(recordContext ?? context.active());
            if (store === undefined) {
                return;
            }
            for (const [key, value] of Object.entries(store.log)) {
                if (record.attributes[key] !== undefined) {
                    continue;
                }
                record.setAttribute(key, value);
            }
        },
        shutdown() {
            return Promise.resolve();
        },
        forceFlush() {
            return Promise.resolve();
        },
    };
}
